export const PERSONA_VIEWS: Record<string, PersonaView[]> = {
  "pregnancy-w8": [{"persona":"partner","headline":"The first trimester is quiet work","body":"She may be exhausted and not look pregnant at all. The tiredness is the pregnancy, not a lack of interest in you.","actions":[{"id":"w8-partner-shift","type":"do","priority":"recommended","domain":"home","title":"Take the evening shift","why":"Cook, wash up, walk the dog. The hour she does not spend standing is the hour she gets back.","minutes":45,"options":[]},{"id":"w8-partner-appt","type":"do","priority":"recommended","domain":"health-parent","title":"Go to the first appointment","why":"The first visit is a long wait and a lot of questions. Two sets of ears remember more.","minutes":90,"options":[]}]},{"persona":"grandparent","headline":"You know a lot. Some of it has changed.","body":"The advice you were given was good advice then. A short list of things has genuinely changed, and the cot is on it.","actions":[{"id":"w8-grandparent-sleep","type":"know","priority":"recommended","domain":"safety","title":"Learn the sleep rules before you babysit","why":"On the back, on a firm surface, nothing in the cot. This is the one where old advice is now dangerous.","minutes":10,"options":[]},{"id":"w8-grandparent-ask","type":"ask","priority":"recommended","domain":"mind","title":"Ask before you tell","why":"A question opens a door and a sentence closes one. \"How are you feeling?\" gets an answer.","minutes":5,"options":[]}]}],
  "pregnancy-w20": [{"persona":"partner","headline":"Halfway, and the list is longer than the bump","body":"The middle months are the easy ones. The cot, the class, the car seat and the pediatrician are all easier to sort now than at 38 weeks.","actions":[{"id":"w20-partner-cot","type":"do","priority":"recommended","domain":"home","title":"Build the cot before the bump","why":"Assembling furniture at eight months pregnant, in a small room, is a two-person job and an argument.","minutes":120,"options":[]},{"id":"w20-partner-class","type":"book","priority":"recommended","domain":"health-parent","title":"Book the birth class","why":"You will both be in the room. Knowing the words for what is happening is not a spectator sport.","minutes":60,"options":[]}]},{"persona":"grandparent","headline":"The useful grandparent has a car and no opinions","body":"By now she has heard every warning twice. What she has not got is somebody who can drive to the 8am appointment.","actions":[{"id":"w20-grandparent-lift","type":"do","priority":"recommended","domain":"home","title":"Take a morning off for an appointment","why":"The 20-week scan is the long one. A lift and a coffee afterwards is worth more than a cot.","minutes":120,"options":[]},{"id":"w20-grandparent-gift","type":"buy","priority":"recommended","domain":"gear","title":"Give the thing they will not buy","why":"Nappies, a cleaner, a meal. Not another outfit in newborn size.","minutes":20,"noChooser":"There is no chooser for nappies. Buy the size on their list and keep the receipt.","options":[]}]},{"persona":"extended","headline":"The fun aunt or uncle is a real job","body":"You are not the parent and not the grandparent. You can be delighted without being responsible, and that is a better position than it sounds.","actions":[{"id":"w20-extended-list","type":"buy","priority":"recommended","domain":"gear","title":"Buy from the list, not the shop","why":"They wrote a list for a reason. The fourth muslin is not the gift; the thing nobody bought is.","minutes":20,"noChooser":"The list is the chooser. Anything off it is a guess, and they will be polite about it.","options":[]},{"id":"w20-extended-plan","type":"do","priority":"recommended","domain":"home","title":"Plan one thing for after the birth","why":"A meal, a walk, an afternoon of company. Week three is when the visitors stop and the help is still needed.","minutes":30,"options":[]}]}],
  "pregnancy-w28": [{"persona":"partner","headline":"The third trimester starts with a list","body":"From here the appointments are every two weeks, then every week. Somebody has to drive, and somebody has to remember what was said.","actions":[{"id":"w28-partner-drive","type":"do","priority":"recommended","domain":"health-parent","title":"Take the appointments off her plate","why":"The glucose test, the growth checks, the weekly visits. Book the time off now, before the calendar fills.","minutes":60,"options":[]},{"id":"w28-partner-bag","type":"do","priority":"recommended","domain":"home","title":"Start the hospital bag","why":"A bag packed at 36 weeks is calm. A bag packed at 3am in labour is a shopping trip.","minutes":30,"options":[]}]},{"persona":"grandparent","headline":"Be reachable, not resident","body":"The last months are a waiting room. Being available at 2am is worth more than being in the kitchen at 2pm.","actions":[{"id":"w28-grandparent-dog","type":"do","priority":"recommended","domain":"home","title":"Agree what happens to the dog","why":"The plan nobody made is the one that goes wrong on the night.","minutes":15,"options":[]},{"id":"w28-grandparent-freezer","type":"do","priority":"recommended","domain":"nutrition","title":"Fill the freezer","why":"The first week at home has no cooking in it. Lasagne in portions is love with a date on it.","minutes":90,"options":[]}]}],
  "pregnancy-w37": [{"persona":"partner","headline":"You are on call now","body":"From 37 weeks the answer to \"is this it?\" can be yes. Know the route, the bag, and who is driving.","actions":[{"id":"w37-partner-bag-car","type":"do","priority":"recommended","domain":"home","title":"Put the bag in the car","why":"The bag by the door is a plan. The bag in the car is a decision already made.","minutes":15,"options":[]},{"id":"w37-partner-triage","type":"know","priority":"recommended","domain":"health-parent","title":"Save the triage number","why":"It is on the fridge in this week's pack. Put it in your phone too, because you will be the one dialling.","minutes":5,"options":[]}]},{"persona":"grandparent","headline":"The phone stays on","body":"The call may come at three in the morning. That is the whole job this month.","actions":[{"id":"w37-grandparent-phone","type":"do","priority":"recommended","domain":"home","title":"Keep the phone on at night","why":"A silenced phone at 3am is a missed birth. Turn the ringer on and put it by the bed.","minutes":2,"options":[]},{"id":"w37-grandparent-food","type":"do","priority":"recommended","domain":"nutrition","title":"Cook one meal they can reheat","why":"Not a feast. One thing, in portions, that goes in the oven from frozen.","minutes":60,"options":[]}]}],
  "postpartum-week-1": [{"persona":"partner","headline":"Nobody is themselves in the first week","body":"She is healing, feeding around the clock and running on broken sleep. The most useful thing you own is the ability to take the baby for an hour.","actions":[{"id":"pp1-partner-feed","type":"do","priority":"recommended","domain":"feeding","title":"Own one night feed","why":"One feed you do without waking her is the difference between four hours of sleep and two.","minutes":40,"options":[]},{"id":"pp1-partner-gate","type":"do","priority":"recommended","domain":"home","title":"Be the one who says no","why":"You are the gatekeeper. \"Not today\" is easier to hear from you than from her.","minutes":5,"options":[]}]},{"persona":"grandparent","headline":"Hold the baby. Wash the dishes.","body":"The visit that helps is the one where you do the boring thing and leave. The visit that hurts is the one where you hold the baby and she makes the tea.","actions":[{"id":"pp1-grandparent-chore","type":"do","priority":"recommended","domain":"home","title":"Do one chore without asking","why":"Not \"what can I do\". The dishes. The bin. The laundry sitting in the machine.","minutes":20,"options":[]},{"id":"pp1-grandparent-short","type":"do","priority":"recommended","domain":"mind","title":"Keep the visit short","why":"Forty minutes, then go. A new parent is hosting you whether they meant to or not.","minutes":40,"options":[]}]},{"persona":"extended","headline":"Week three is the week they need you","body":"In the first week there are too many people. In the third there is nobody, and the doorbell has stopped ringing.","actions":[{"id":"pp1-extended-later","type":"do","priority":"recommended","domain":"home","title":"Offer to come in week three","why":"Say the date now, so nobody has to ask. The first week is for grandparents and sleep.","minutes":5,"options":[]},{"id":"pp1-extended-sick","type":"know","priority":"recommended","domain":"safety","title":"Stay away if you are ill","why":"A cold in a newborn is a hospital visit. A cold in you is a week off. Reschedule.","minutes":2,"options":[]}]}],
  "postpartum-week-6": [{"persona":"partner","headline":"Week six is when it gets quiet","body":"The visitors have gone, the adrenaline has gone, and the work is still here. This is the week to check on her, not the baby.","actions":[{"id":"pp6-partner-mood","type":"ask","priority":"recommended","domain":"mind","title":"Ask how she is, and wait","why":"Postpartum depression is common and quiet. \"How are you, really?\" asked twice is a different question.","minutes":10,"options":[]},{"id":"pp6-partner-hour","type":"do","priority":"recommended","domain":"mind","title":"Take the baby for an hour, awake","why":"Not so she can sleep. So she can be a person who is not on duty.","minutes":60,"options":[]}]},{"persona":"grandparent","headline":"The quiet week","body":"By now the help has thinned out and the tiredness has not. A standing offer is worth more than a visit.","actions":[{"id":"pp6-grandparent-regular","type":"do","priority":"recommended","domain":"home","title":"Set a weekly time and keep it","why":"A Tuesday morning every week beats a big visit once. Predictable help is easier to accept.","minutes":60,"options":[]},{"id":"pp6-grandparent-signs","type":"know","priority":"recommended","domain":"mind","title":"Know the signs to watch for","why":"If she is not sleeping when the baby sleeps, or says she feels nothing, that is worth a call to her doctor.","minutes":10,"options":[]}]}],
  "infant-month-6": [{"persona":"partner","headline":"Six months in, the novelty is gone","body":"The baby is more fun and the work is the same. This is the stretch that quietly wears couples down, and it is survivable.","actions":[{"id":"m6-partner-split","type":"do","priority":"recommended","domain":"home","title":"Write down who does what","why":"The invisible list is the argument. Writing it down makes it visible, and divisible.","minutes":20,"options":[]},{"id":"m6-partner-night","type":"do","priority":"recommended","domain":"sleep","title":"Take one night wake","why":"Teething wakes everybody. One of you getting up every time is how two people end up exhausted.","minutes":30,"options":[]}]},{"persona":"grandparent","headline":"The baby is not yours to raise","body":"The hardest part of this year is watching your child do it differently from how you did it, and saying nothing.","actions":[{"id":"m6-grandparent-advice","type":"know","priority":"recommended","domain":"mind","title":"Answer only what is asked","why":"If they ask how you did it, tell them. If they do not, the silence is the help.","minutes":5,"options":[]},{"id":"m6-grandparent-photo","type":"do","priority":"recommended","domain":"safety","title":"Ask before you post a photo","why":"A photograph on your page is a photograph on the internet, permanently, with their name attached.","minutes":5,"options":[]}]},{"persona":"extended","headline":"Be the one who is not keeping score","body":"By now everyone has an opinion about the sleep, the feeding and the screens. You can be the one who asks and does not grade the answer.","actions":[{"id":"m6-extended-task","type":"do","priority":"recommended","domain":"home","title":"Turn up with a task","why":"Not to hold the baby. To walk it round the block so she can eat with two hands.","minutes":30,"options":[]},{"id":"m6-extended-song","type":"do","priority":"recommended","domain":"play","title":"Learn one song they like","why":"A song you can sing badly is worth more to a six-month-old than a toy that needs batteries.","minutes":15,"options":[]}]}],
  "infant-month-12": [{"persona":"partner","headline":"The first birthday is a milestone for you too","body":"You have kept a person alive for a year. The next year is less about keeping them alive and more about keeping up.","actions":[{"id":"m12-partner-review","type":"ask","priority":"recommended","domain":"mind","title":"Ask what the last year cost her","why":"Not the money. The sleep, the body, the job, the friends. Saying it out loud is the point.","minutes":30,"options":[]},{"id":"m12-partner-proof","type":"do","priority":"recommended","domain":"safety","title":"Do the childproofing pass","why":"At twelve months everything is reachable. Walk the room at their height and move what is not.","minutes":45,"options":[]}]},{"persona":"grandparent","headline":"You made it through the first year too","body":"Whatever you got wrong this year, the baby is one and your child is still speaking to you. That is a good year.","actions":[{"id":"m12-grandparent-regular","type":"do","priority":"recommended","domain":"home","title":"Be the regular, not the event","why":"A Tuesday every week beats a party once a year. Children remember who was always there.","minutes":60,"options":[]},{"id":"m12-grandparent-listen","type":"know","priority":"recommended","domain":"mind","title":"Let them set the birthday rules","why":"Who is invited, what is eaten, whether there is a nap. It is their party now.","minutes":5,"options":[]}]}],
  "toddler-month-24": [{"persona":"partner","headline":"You are the other half of the discipline","body":"A two-year-old learns what is allowed by testing both of you. Two different answers is a lesson in which parent to ask.","actions":[{"id":"m24-partner-rule","type":"do","priority":"recommended","domain":"mind","title":"Agree on the one rule","why":"Pick the thing you will both hold, and hold it the same way. One rule held is worth ten announced.","minutes":20,"options":[]},{"id":"m24-partner-out","type":"do","priority":"recommended","domain":"play","title":"Take them out on your own","why":"An hour at the park, without her, is an hour she is not being climbed on.","minutes":60,"options":[]}]},{"persona":"grandparent","headline":"You are the safe place with the boring rules","body":"A toddler who knows your house has the same rules as their house is a toddler who can relax. That is the gift.","actions":[{"id":"m24-grandparent-rules","type":"do","priority":"recommended","domain":"home","title":"Match their rules at your house","why":"If the cot has no blanket at home, it has no blanket at yours. Consistency is what makes you restful.","minutes":15,"options":[]},{"id":"m24-grandparent-backup","type":"know","priority":"recommended","domain":"mind","title":"Back the parent up in front of the child","why":"Disagree later, in the kitchen. A toddler who sees you overrule a parent learns to shop for the softer answer.","minutes":5,"options":[]}]},{"persona":"extended","headline":"This is when you become the fun one","body":"A two-year-old cannot be charmed, but can be delighted. You are the person with no rules to enforce and no bedtime to defend.","actions":[{"id":"m24-extended-out","type":"do","priority":"recommended","domain":"play","title":"Take them somewhere with weather","why":"Puddles, sticks, a hill. The outing that costs nothing is the one they talk about.","minutes":90,"options":[]},{"id":"m24-extended-ask","type":"know","priority":"recommended","domain":"mind","title":"Ask the parent first","why":"A sweet before dinner is not your call. Ask once, in front of the child, and take the answer.","minutes":2,"options":[]}]}],
  "toddler-month-36": [{"persona":"partner","headline":"Three is the year of the question","body":"\"Why?\" is not defiance, it is the job. Answering the fourth one badly is not a failure.","actions":[{"id":"m36-partner-why","type":"know","priority":"recommended","domain":"play","title":"Answer the fourth why","why":"The fourth question is usually the real one. Answering it is the difference between a conversation and a wall.","minutes":10,"options":[]},{"id":"m36-partner-nursery","type":"do","priority":"recommended","domain":"childcare","title":"Decide on the nursery or preschool now","why":"The good ones have waitlists that run a year. This is the week the list is still short.","minutes":60,"options":[]}]},{"persona":"grandparent","headline":"Three is when they start to remember you","body":"A three-year-old keeps the things you do. The walk, the biscuit, the song in the car. This is the year it becomes memory.","actions":[{"id":"m36-grandparent-memory","type":"do","priority":"recommended","domain":"play","title":"Start one thing that is only yours","why":"A walk, a biscuit, a song in the car. One repeated thing is what a three-year-old keeps.","minutes":30,"options":[]},{"id":"m36-grandparent-ask","type":"ask","priority":"recommended","domain":"mind","title":"Ask what they need before you offer","why":"The offer you would have made last year may not be the one they need now.","minutes":5,"options":[]}]}],
};

